 assert.deepEqual(automatic.rows.find(r=>r.employeeId==='SHEETS-1').branches,['MIAMI','FOUAD','ABU-QEER','ASWAN']);assert.equal(automatic.rows.find(r=>r.employeeId==='SHEETS-1').sources.length,2);
